import { useEffect, useState, type ReactNode } from "react";
import { api } from "./api";
import { CanonicalFormsLibrary } from "./MasterContentForms";
import { readDemoRole } from "./rebrand";
import { OwnerDecisionCenterPage } from "./OwnerDecisionCenter";
import { BillingInvoicePage } from "./BillingInvoice";

type AdminCategory = { key: string; label: string; route: string; status: string };

const groups = [
  { label: "People & Access", keys: ["people-access"] },
  { label: "Data & Connections", keys: ["data-connections"] },
  { label: "Project & Folder Setup", keys: ["project-folder-setup"] },
  { label: "Proposals & Contracts", keys: ["proposal-setup", "contract-setup", "forms", "templates", "owner-decisions"] },
  { label: "Permit Workflow", keys: ["permit-setup"] },
  { label: "Operations", keys: ["notifications"] },
  { label: "System", keys: ["security", "integration-health", "audit"] },
  { label: "Advanced", keys: ["advanced-diagnostics"] },
];

const endpointFor = (path: string) => {
  const key = path.replace(/^\/admin\/?/, "");
  const apiKeys: Record<string, string> = {
    "data-connections": "connections", "project-folder-setup": "project-setup", "proposal-setup": "proposal-setup",
    "contract-setup": "contract-setup", "permit-setup": "permit-setup", templates: "templates", forms: "master-content-forms", notifications: "notifications",
    security: "security", "integration-health": "integration-health", audit: "audit", "people-access": "users",
  };
  if (key === "advanced-diagnostics" || key.startsWith("advanced-diagnostics/") || key === "control-diagnostics") return "/api/admin/advanced-diagnostics";
  if (key === "contracts/inputs/go-live") return "/api/admin/contracts/inputs/go-live";
  if (key === "owner-decisions") return "/api/owner-decisions";
  if (key === "invoices") return "/api/billing/invoices";
  if (key.startsWith("invoices/")) return `/api/billing/invoices/${key.split("/")[1]}`;
  if (key === "contracts") return "/api/admin/contracts?filter=ALL";
  if (key.startsWith("contracts/")) return `/api/admin/contracts/${key.split("/")[1]}`;
  // Retired direct Admin aliases keep a safe, current summary response instead of
  // issuing a dead endpoint request. Navigation remains available through the
  // current Owner Administration groups.
  if (key === "forms") return "/api/master-content?content_type=FORM";
  return key ? `/api/admin/${apiKeys[key] || "summary"}` : "/api/admin/summary";
};

const human = (value: unknown, fallback = "Needs AMEC Input") => {
  if (value === null || value === undefined || value === "") return fallback;
  return String(value).replaceAll("_", " ").replaceAll("QUOTATION", "PROPOSAL").replaceAll("Quotation", "Proposal");
};

const statusText = (value: unknown) => human(value, "Needs AMEC Input");

export function AdministrationOwnerPage() {
  const [path, setPath] = useState(window.location.pathname);
  const [data, setData] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const endpoint = endpointFor(path);
  const load = () => { setLoading(true); setError(""); api<any>(endpoint).then(setData).catch((cause) => setError(cause instanceof Error ? cause.message : "Administration is unavailable.")).finally(() => setLoading(false)); };
  const go = (route: string) => { window.history.pushState({}, "", route); window.dispatchEvent(new PopStateEvent("popstate")); };
  useEffect(() => { const sync = () => setPath(window.location.pathname); window.addEventListener("popstate", sync); return () => window.removeEventListener("popstate", sync); }, []);
  useEffect(() => { setData(null); load(); }, [endpoint]);
  if (loading) return <AdminShell path={path} onNavigate={go}><section className="admin-owner-panel"><b>Loading Administration…</b></section></AdminShell>;
  if (error) return <AdminShell path={path} onNavigate={go}><section className="admin-owner-panel admin-owner-error" role="alert"><h2>Administration unavailable</h2><p>{error}</p><button className="button-primary" onClick={load}>Retry</button></section></AdminShell>;
  if (path === "/admin/contracts/inputs/go-live") return <AdminShell path={path} onNavigate={go}><ContractInputs data={data} /></AdminShell>;
  if (path === "/admin/owner-decisions") return <AdminShell path={path} onNavigate={go}><OwnerDecisionCenterPage /></AdminShell>;
  if (path === "/admin/contracts") return <AdminShell path={path} onNavigate={go}><OperationalContracts onNavigate={go} /></AdminShell>;
  if (path === "/admin/invoices" || path.startsWith("/admin/invoices/")) return <AdminShell path={path} onNavigate={go}><BillingInvoicePage /></AdminShell>;
  if (path.startsWith("/admin/contracts/")) return <AdminShell path={path} onNavigate={go}><ContractWorkbench data={data} onBack={() => go("/admin/contracts")} onRefresh={load} onNavigate={go} /></AdminShell>;
  return <AdminShell path={path} onNavigate={go}>{path === "/admin" || path === "/admin/" ? <Landing data={data} onNavigate={go} /> : <Section path={path} data={data} onNavigate={go} onRefresh={load} />}</AdminShell>;
}

function AdminShell({ path, onNavigate, children }: { path: string; onNavigate: (route: string) => void; children: ReactNode }) {
  const label = path === "/admin" ? "Administration" : path === "/admin/contracts" ? "Contracts" : path.startsWith("/admin/contracts/") && !path.endsWith("/inputs/go-live") ? "Contract Workspace" : path.startsWith("/admin/invoices") ? "Invoices" : path.split("/").pop()?.replaceAll("-", " ").replace(/\b\w/g, (letter) => letter.toUpperCase()) || "Administration";
  return <div className="workflow-page admin-owner-page"><div className="page-intro admin-owner-intro"><div><span className="eyebrow">AMEC · ADMINISTRATION</span><h2>{label}</h2><p>{path === "/admin" ? "Manage contracts, invoices, project activation, and administrative follow-up." : "Owner business administration; operational tasks remain in AMEC Work."}</p></div><span className="tag admin-context-chip">Business Record</span></div><div className="admin-owner-environment">SYNTHETIC PROTOTYPE · Test data and simulated connections</div>{path !== "/admin" && <button className="admin-owner-back" onClick={() => onNavigate("/admin")}>← Administration</button>}{children}</div>;
}

function Landing({ data, onNavigate }: { data: any; onNavigate: (route: string) => void }) {
  const [contracts, setContracts] = useState<any[]>([]);
  const [contractCounts, setContractCounts] = useState<Record<string, number>>({ ALL: 0, NEEDS_ACTION: 0, AUTHORITY_REVIEW: 0, READY_CLOSE: 0 });
  const [invoices, setInvoices] = useState<any[]>([]);
  const [invoiceCounts, setInvoiceCounts] = useState<Record<string, number>>({ ALL: 0, NEED_ACTION: 0, AUTHORITY_REVIEW: 0, READY_CLOSE: 0 });
  const [error, setError] = useState("");
  const load = async () => {
    setError("");
    try {
      const contractResponses = await Promise.all(contractLanes.map(([key]) => api<any>(`/api/admin/contracts?filter=${key}`)));
      setContractCounts(Object.fromEntries(contractLanes.map(([key], index) => [key, contractResponses[index].count ?? contractResponses[index].items?.length ?? 0])));
      setContracts((contractResponses[0].items || []).slice(0, 5));
      const invoiceResponse = await api<any>("/api/billing/invoices");
      setInvoices((invoiceResponse.items || []).slice(0, 5));
      setInvoiceCounts({ ALL: invoiceResponse.lanes?.all ?? invoiceResponse.total ?? 0, NEED_ACTION: invoiceResponse.lanes?.need_action ?? 0, AUTHORITY_REVIEW: invoiceResponse.lanes?.authority_review ?? 0, READY_CLOSE: invoiceResponse.lanes?.ready_close ?? 0 });
    } catch (cause) {
      setContracts([]);
      setInvoices([]);
      setContractCounts({ ERROR: 1 });
      setInvoiceCounts({ ERROR: 1 });
      setError(cause instanceof Error ? cause.message : "Administration summary could not be loaded.");
    }
  };
  useEffect(() => { void load(); }, []);
  return <>
    <div className="admin-owner-lead"><div><h3>Owner summary and pending inputs</h3><p>Administration keeps active Contract and Invoice work together. Tasks remain in AMEC Work; blockers remain in Issues.</p></div><button className="button-secondary" onClick={() => onNavigate(data.go_live?.route || "/admin/go-live-readiness")}>Inputs &amp; Go-Live</button></div>
    {error && <div className="admin-owner-error" role="alert"><b>Could not load Administration summary</b><p>{error}</p><button className="button-primary" onClick={() => void load()}>Retry</button></div>}
    <OperationalPreview title="Contracts" eyebrow="ADMINISTRATION · CONTRACTS" counts={contractCounts} countKeys={contractLanes} onViewAll={() => onNavigate("/admin/contracts")} onCreate={() => onNavigate("/admin/contracts")} createLabel="+ New Contract" createHint="Create from an eligible Accepted Proposal" columns={["Contract", "Client", "Stage", "Amount", "Next Action", "Open"]}>
      {contracts.map((item) => <div className="admin-owner-row admin-operational-preview-row" key={item.id}><div><b>{item.contract_reference || item.contract_ref}</b><small>{item.contract_name || item.contract || "Contract"}</small></div><span>{item.client?.name || "Client pending"}</span><em>{ownerStage(item.stage)}</em><span>{item.amount ? `${item.amount} ${item.currency || ""}` : "—"}</span><span>{ownerNextAction(item.next_action, item.stage)}</span><button className="text-button" onClick={() => onNavigate(`/admin/contracts/${item.id}`)}>Open →</button></div>)}
    </OperationalPreview>
    <OperationalPreview title="Invoices" eyebrow="ADMINISTRATION · INVOICES" counts={invoiceCounts} countKeys={[["ALL", "All"], ["NEED_ACTION", "Need Action"], ["AUTHORITY_REVIEW", "Authority Review"], ["READY_CLOSE", "Ready / Close"]]} onViewAll={() => onNavigate("/admin/invoices")} columns={["Invoice", "Contract / Project", "Stage", "Amount", "Due / Outstanding", "Open"]}>
      {invoices.map((item) => <div className="admin-owner-row admin-operational-preview-row" key={item.invoice.id}><div><b>{item.invoice.invoice_reference}</b><small>{ownerStage(item.stage)}</small></div><span>{item.contract?.contract_reference || "Contract context"}{item.project?.project_code ? ` · ${item.project.project_code}` : ""}</span><em>{ownerStage(item.invoice.status)}</em><span>{item.revision?.payable_total ?? "—"} {item.revision?.currency || ""}</span><span>{item.revision?.due_date || "Not due"} · {ownerStage(item.receivable?.state)}</span><button className="text-button" onClick={() => onNavigate(`/admin/invoices/${item.invoice.id}`)}>Open →</button></div>)}
    </OperationalPreview>
    <div className="admin-owner-secondary-links"><button className="admin-owner-secondary-link" onClick={() => onNavigate("/handover")}><b>Handover &amp; Closeout</b><span>Service closure, Contract Administrative Closure, settlement boundary, and archive gates.</span>Open Handover &amp; Closeout →</button><button className="admin-owner-secondary-link" onClick={() => onNavigate("/admin/setup-controls")}><b>Setup &amp; Controls</b><span>Users, connections, templates, notifications, security, audit, and diagnostics.</span>Open Setup &amp; Controls →</button></div>
  </>;
}

function OperationalPreview({ title, eyebrow, counts, countKeys, columns, children, onViewAll, onCreate, createLabel, createHint }: { title: string; eyebrow: string; counts: Record<string, number>; countKeys: readonly (readonly [string, string])[]; columns: string[]; children: ReactNode; onViewAll: () => void; onCreate?: () => void; createLabel?: string; createHint?: string }) {
  const hasChildren = Array.isArray(children) ? children.length > 0 : Boolean(children);
  if (counts.ERROR) return <section className="admin-owner-panel admin-operational-preview"><div className="admin-owner-panel-heading"><div><span className="eyebrow">{eyebrow}</span><h3>{title}</h3></div><span className="admin-owner-status">Unavailable</span></div><div className="admin-owner-error" role="status"><b>{title} summary unavailable</b><p>Use Retry above to reload the live register.</p></div></section>;
  return <section className="admin-owner-panel admin-operational-preview"><div className="admin-owner-panel-heading"><div><span className="eyebrow">{eyebrow}</span><h3>{title}</h3></div><div className="admin-operational-preview-actions">{onCreate && <button className="button-primary" onClick={onCreate} title={createHint}> {createLabel} </button>}<button className="button-secondary" onClick={onViewAll}>View all {title}</button></div></div><div className="filter-row admin-operational-preview-lanes" role="tablist" aria-label={`${title} lanes`}>{countKeys.map(([key, label]) => <span className="filter" key={key}>{label}<strong>{counts[key] ?? 0}</strong></span>)}</div><div className="admin-owner-table admin-operational-preview-table"><div className="admin-permission-head">{columns.map((column) => <b key={column}>{column}</b>)}</div>{children}{!hasChildren && <div className="empty-state">No {title.toLowerCase()} are currently available.</div>}</div></section>;
}

const ownerStage = (value: unknown) => ({ DRAFT: "Contract Draft", NEEDS_ACTION: "Needs Action", AUTHORITY_REVIEW: "Authority Review", READY: "Ready for activation", READY_CLOSE: "Ready / Close", ACTIVE: "Active", CLOSED: "Closed", FINALIZED: "Accepted", APPROVED: "Approved", ACCEPTED_INTERNAL: "Accepted internally", ISSUED: "Issued", NOT_ISSUED: "Not issued", NEED_ACTION: "Needs Action", NOT_READY: "Not ready", AWAITING_DUE_EVENT: "Awaiting due event", PARTIALLY_PAID: "Partially paid", PAID: "Paid" }[String(value || "").toUpperCase()] || human(value, "Not configured"));
const ownerNextAction = (value: unknown, stage: unknown) => value ? human(value) : String(stage || "").toUpperCase() === "DRAFT" ? "Review Contract" : "No action recorded";

const contractLanes = [["ALL", "All"], ["NEEDS_ACTION", "Need Action"], ["AUTHORITY_REVIEW", "Authority Review"], ["READY_CLOSE", "Ready / Close"]] as const;

function OperationalContracts({ onNavigate }: { onNavigate: (route: string) => void }) {
  const [lane, setLane] = useState("ALL");
  const [query, setQuery] = useState("");
  const [items, setItems] = useState<any[]>([]);
  const [counts, setCounts] = useState<Record<string, number>>({ ALL: 0, NEEDS_ACTION: 0, AUTHORITY_REVIEW: 0, READY_CLOSE: 0 });
  const [proposals, setProposals] = useState<any[]>([]);
  const [proposalId, setProposalId] = useState("");
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");
  const load = async (nextLane = lane, nextQuery = query) => {
    setError("");
    try {
      const laneResponses = await Promise.all(contractLanes.map(([key]) => api<any>(`/api/admin/contracts?q=${encodeURIComponent(nextQuery)}&filter=${key}`)));
      setCounts(Object.fromEntries(contractLanes.map(([key], index) => [key, laneResponses[index].count ?? laneResponses[index].items?.length ?? 0])));
      setItems(laneResponses[contractLanes.findIndex(([key]) => key === nextLane)]?.items || []);
      const proposalData = await api<any>("/api/bd/proposals");
      setProposals((proposalData.items || []).filter((item: any) => item.contract_eligible));
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : "Contracts could not be loaded.");
    }
  };
  useEffect(() => { void load("ALL", ""); }, []);
  const selectLane = (nextLane: string) => { setLane(nextLane); void load(nextLane, query); };
  const search = () => { void load(lane, query); };
  const create = async () => {
    if (!proposalId) { setMessage("Select an accepted Proposal revision before creating a Contract."); return; }
    setMessage("");
    try {
      const result = await api<any>("/api/admin/contracts", { method: "POST", body: JSON.stringify({ proposal_id: proposalId }) });
      onNavigate(`/admin/contracts/${result.id}`);
    } catch (cause) { setMessage(cause instanceof Error ? cause.message : "Contract could not be created. The accepted Proposal remains unchanged."); }
  };
  return <section className="admin-owner-panel admin-operational-register"><div className="admin-owner-panel-heading"><div><span className="eyebrow">ADMINISTRATION · CONTRACTS</span><h3>Contracts</h3><p className="admin-owner-copy">One canonical Contract register sourced from the accepted Proposal revision and current Contract readiness.</p></div><span className="admin-owner-status">{counts.ALL} accessible</span></div><div className="admin-operational-toolbar"><div className="filter-row" role="tablist" aria-label="Contract lanes">{contractLanes.map(([key, label]) => <button key={key} className={`filter ${lane === key ? "active" : ""}`} role="tab" aria-selected={lane === key} onClick={() => selectLane(key)}>{label}<strong>{counts[key]}</strong></button>)}</div><div className="admin-operational-actions"><input aria-label="Search Contracts" placeholder="Search Contract, Client, or Project ref" value={query} onChange={(event) => setQuery(event.target.value)} onKeyDown={(event) => { if (event.key === "Enter") search(); }} /><button className="button-secondary" onClick={search}>Search</button><select aria-label="Accepted Proposal for new Contract" value={proposalId} onChange={(event) => setProposalId(event.target.value)}><option value="">Select accepted Proposal…</option>{proposals.map((item) => <option key={item.id} value={item.id}>{item.proposal || item.proposal_description || "Proposal"} · {item.proposal_reference || item.reference || "Accepted"}</option>)}</select><button className="button-primary" onClick={create} disabled={!proposalId} title={!proposalId ? "Select an accepted Proposal first" : "Create a Contract draft"}>+ New Contract</button></div></div>{error && <div className="admin-owner-error" role="alert"><b>Could not load Contracts</b><p>{error}</p><button className="button-primary" onClick={() => void load(lane, query)}>Retry</button></div>}{message && <div className="admin-owner-message" role="status">{message}</div>}<div className="admin-owner-table contract-owner-list"><div className="admin-permission-head"><b>Contract</b><b>Contract Ref</b><b>Stage</b><b>Amount</b><b>Close Date</b><b>Open</b></div>{items.map((item) => <div className="admin-owner-row" key={item.id}><div><b>{item.contract_name || item.contract || "Unnamed Contract"}</b><small>{item.client?.name || "Client pending"} · {item.project_opportunity_ref || "Project / Opportunity Ref pending"}{item.project_code ? ` · Project Code: ${item.project_code}` : ""}</small></div><span>{item.contract_reference || item.contract_ref || "Pending"}</span><em>{String(item.stage || "DRAFT").replaceAll("_", " ")}</em><span>{item.amount ? `${item.amount} ${item.currency || ""}` : "—"}</span><span>{item.close_date || "—"}</span><button className="text-button" onClick={() => onNavigate(`/admin/contracts/${item.id}`)}>Open →</button></div>)}{!items.length && !error && <div className="empty-state"><b>No Contracts in this lane.</b><p>Use + New Contract with an accepted Proposal, or choose another lane.</p></div>}</div><div className="admin-owner-safe"><b>Contract control boundary</b><span>Open shows the same canonical Contract workspace. It does not activate a Project, close a Contract, or create an Invoice.</span></div></section>;
}

function SetupControls({ data, onNavigate }: { data: any; onNavigate: (route: string) => void }) {
  const categories = (data.categories || []) as AdminCategory[];
  return <section className="admin-owner-panel admin-setup-controls"><div className="admin-owner-panel-heading"><div><span className="eyebrow">ADMINISTRATION · SECONDARY</span><h3>Setup &amp; Controls</h3><p className="admin-owner-copy">Configuration and governance surfaces remain available here; Contract and Invoice records stay in the primary workspaces.</p></div><button className="button-secondary" onClick={() => onNavigate("/admin/go-live-readiness")}>View Inputs &amp; Go-Live</button></div><div className="admin-owner-groups">{groups.map((group) => <section className={`admin-owner-group ${group.label === "Advanced" ? "secondary" : ""}`} key={group.label}><div className="admin-owner-group-heading"><h3>{group.label}</h3></div><div className="admin-owner-cards">{group.keys.map((key) => { const item = categories.find((category) => category.key === key); return item ? <button className="admin-owner-card" key={key} onClick={() => onNavigate(item.route)}><span><b>{item.label}</b><small>{cardCopy(key)}</small></span><em>{item.status}</em><strong>→</strong></button> : null; })}</div></section>)}</div></section>;
}

function cardCopy(key: string) {
  const copy: Record<string, string> = { "people-access": "Users, roles, and capability permissions", "data-connections": "Source systems with simulator and production status", "project-folder-setup": "References, folder structure, and semantic mappings", "proposal-setup": "Proposal fields, intake sources, stages, and handoffs", "contract-setup": "Contract rules, fields, and Permit handoff", forms: "Canonical Forms used across AMEC workflows", templates: "Controlled Proposal, Contract, and Permit templates", "permit-setup": "Requirements, applicability, attachments, and Municipality mode", notifications: "Audiences, reminders, and follow-up rules", security: "Data mode, access, MFA, retention, and backups", "integration-health": "Cross-system checks using the canonical status truth", audit: "Owner-readable operational history", "advanced-diagnostics": "Technical evidence and adapter diagnostics" }; return copy[key] || "Configuration and status";
}

function Section({ path, data, onNavigate, onRefresh }: { path: string; data: any; onNavigate: (route: string) => void; onRefresh: () => void }) {
  const key = path.replace(/^\/admin\//, "");
  if (key === "setup-controls") return <SetupControls data={data} onNavigate={onNavigate} />;
  if (key === "people-access") return <People data={data} onNavigate={onNavigate} />;
  if (key === "data-connections") return <Connections data={data} onRefresh={onRefresh} />;
  if (key === "project-folder-setup") return <ProjectSetup data={data} onNavigate={onNavigate} />;
  if (key === "proposal-setup") return <ProposalSetup data={data} onNavigate={onNavigate} />;
  if (key === "contract-setup") return <ContractSetup data={data} onNavigate={onNavigate} />;
  if (key === "forms") return <CanonicalFormsLibrary role={readDemoRole()} surface="ADMINISTRATION" compact />;
  if (key === "permit-setup") return <PermitSetup data={data} />;
  if (key === "templates") return <Templates data={data} />;
  if (key === "notifications") return <Notifications data={data} onRefresh={onRefresh} />;
  if (key === "security") return <Security data={data} />;
  if (key === "integration-health") return <IntegrationHealth data={data} onNavigate={onNavigate} />;
  if (key === "audit") return <Audit data={data} onNavigate={onNavigate} />;
  if (key === "advanced-diagnostics" || key.startsWith("advanced-diagnostics/") || key === "control-diagnostics") return <Advanced data={data} onNavigate={onNavigate} />;
  return <section className="admin-owner-panel"><h3>Administration route unavailable</h3><p>This route is not part of the Owner Administration contract.</p><button className="button-primary" onClick={() => onNavigate("/admin")}>Back to Administration</button></section>;
}

function People({ data, onNavigate }: { data: any; onNavigate: (route: string) => void }) { return <div className="admin-owner-two-col"><section className="admin-owner-panel"><div className="admin-owner-panel-heading"><div><span className="eyebrow">PEOPLE &amp; ACCESS</span><h3>Users &amp; Roles</h3></div><span className="admin-owner-status">{statusText(data.production_user_management)}</span></div><div className="admin-owner-table">{(data.users || []).map((user: any) => <div className="admin-owner-row" key={user.id}><div><b>{user.name}</b><small>{user.email} · {user.office}</small></div><span>{user.role}</span><em>{user.status}</em></div>)}</div><p className="admin-owner-note">Synthetic users illustrate the current role model. Production provisioning remains an AMEC setup input.</p><button className="text-button" onClick={() => onNavigate(data.inputs_route || "/admin/go-live-readiness")}>View what we need from AMEC →</button></section><section className="admin-owner-panel"><span className="eyebrow">CAPABILITY MATRIX</span><h3>What each role can do</h3><div className="admin-permission-table"><div className="admin-permission-head"><b>Capability</b><b>Owner</b><b>Business Development</b><b>Engineering</b></div>{(data.permissions || []).map((row: any) => <div className="admin-permission-row" key={row.capability}><span>{row.capability}</span><span>{row.owner}</span><span>{row.business_development}</span><span>{row.engineering}</span></div>)}</div></section></div>; }

function Connections({ data, onRefresh: _onRefresh }: { data: any; onRefresh: () => void }) { const [message, setMessage] = useState(""); const test = async (name: string) => { setMessage(""); try { const result = await api<any>("/api/admin/connections/test", { method: "POST", body: JSON.stringify({ name }) }); setMessage(`${result.name}: ${result.status} · tested ${new Date(result.tested_at).toLocaleString()}`); } catch (cause) { setMessage(cause instanceof Error ? cause.message : "Connection test failed."); } }; return <section className="admin-owner-panel"><div className="admin-owner-panel-heading"><div><span className="eyebrow">DATA &amp; CONNECTIONS</span><h3>Source Connections</h3></div><span className="admin-owner-status">Credentials masked</span></div><div className="admin-owner-connection-grid">{(data.connections || []).map((connection: any) => <article key={connection.name}><div><b>{connection.name}</b><p>{connection.purpose}</p></div><span className="admin-owner-health">{connection.status}</span><small>{connection.environment} · {connection.production_status}</small><small>{connection.affected_workflow}{connection.last_tested ? ` · Last tested ${new Date(connection.last_tested).toLocaleString()}` : ""}</small><button className="button-secondary" onClick={() => test(connection.name)}>Test connection</button></article>)}</div>{message && <div className="admin-owner-message" role="status">{message}</div>}<p className="admin-owner-note">Simulator status is not production connectivity. Production setup details remain in Inputs &amp; Go-Live.</p></section>; }

function ProjectSetup({ data, onNavigate }: { data: any; onNavigate: (route: string) => void }) { return <div className="admin-owner-two-col"><section className="admin-owner-panel"><span className="eyebrow">PROJECT &amp; FOLDER SETUP</span><h3>References and project identity</h3><div className="admin-owner-definition-list"><b>Proposal before Project</b><span>{data.reference_behavior?.proposal_before_project}</span><b>Canonical Project Reference</b><span>{data.reference_behavior?.project_reference}</span><b>Lineage</b><span>{data.reference_behavior?.lineage}</span><b>Demo scenario</b><span>{data.scenario?.project_type} · {data.scenario?.municipality} · {data.scenario?.status}</span></div><p className="admin-owner-note">The displayed references and folders are synthetic examples; AMEC production numbering and root location remain setup inputs.</p></section><section className="admin-owner-panel"><span className="eyebrow">FOLDER STRUCTURE</span><h3>Semantic source mappings</h3>{(data.folder_structure || []).map((item: any) => <div className="admin-owner-row" key={item.category}><div><b>{item.category}</b><small>{item.mapping} · {item.reconciliation}</small></div><em>{item.status}</em></div>)}<div className="admin-owner-definition-list"><b>Root mapping</b><span>{data.root_mapping}</span><b>Template version</b><span>{data.folder_template_version}</span><b>Excel project register</b><span>{data.excel_mapping?.status}{data.excel_mapping?.project_reference ? ` · ${data.excel_mapping.project_reference}` : ""}</span></div><button className="text-button" onClick={() => onNavigate("/admin/go-live-readiness")}>View what we need from AMEC →</button></section></div>; }

function ProposalSetup({ data, onNavigate }: { data: any; onNavigate: (route: string) => void }) { return <section className="admin-owner-panel"><span className="eyebrow">PROPOSAL SETUP</span><h3>Proposal workflow configuration</h3><p className="admin-owner-copy">These fields, sources, and handoffs are derived from the current Proposal intake and preparation contract. Requiredness remains backend-controlled.</p><h4>Required Proposal intake fields</h4><div className="admin-owner-chip-grid">{(data.required_fields || []).map((item: any) => <div key={item.key}><b>{item.label}</b><span>{item.status}</span></div>)}</div><h4>Allowed intake sources</h4><div className="admin-owner-chip-grid">{(data.source_types || []).map((item: any) => <div key={item.key}><b>{item.label}</b><small>{item.purpose}</small><span>{item.status}</span></div>)}</div><div className="admin-owner-definition-list"><b>Current demo stage</b><span>{data.lifecycle?.current_demo_stage}</span><b>Readiness</b><span>{data.lifecycle?.readiness}</span><b>Handoffs</b><span>{(data.handoffs || []).map((item: any) => `${item.from} → ${item.to}: ${item.when}`).join(" · ")}</span><b>Reference rule</b><span>{data.reference_rule}</span></div><button className="text-button" onClick={() => onNavigate(data.template_route || "/admin/templates")}>View templates →</button></section>; }

function LegacyContractSetup({ data, onNavigate }: { data: any; onNavigate: (route: string) => void }) {
  const [contracts, setContracts] = useState<any[]>([]);
  const [proposals, setProposals] = useState<any[]>([]);
  const [filter, setFilter] = useState("ALL");
  const [proposalId, setProposalId] = useState("");
  const [message, setMessage] = useState("");
  const load = () => Promise.all([api<any>("/api/admin/contracts"), api<any>("/api/bd/proposals")]).then(([contractData, proposalData]) => { setContracts(contractData.items || []); setProposals((proposalData.items || []).filter((item: any) => item.contract_eligible)); }).catch((cause) => setMessage(cause instanceof Error ? cause.message : "Contract list unavailable."));
  useEffect(() => { void load(); }, []);
  const create = async () => { setMessage(""); if (!proposalId) { setMessage("Select an accepted Proposal revision first."); return; } try { const result = await api<any>("/api/admin/contracts", { method: "POST", body: JSON.stringify({ proposal_id: proposalId }) }); onNavigate(`/admin/contracts/${result.id}`); } catch (cause) { setMessage(cause instanceof Error ? cause.message : "Contract could not be created."); } };
  const visible = contracts.filter((item) => filter === "ALL" || (filter === "READY_CLOSE" ? ["READY", "ACTIVE", "CLOSED"].includes(item.stage) : item.stage === filter || (filter === "NEEDS_ACTION" && ["DRAFT", "NEEDS_ACTION"].includes(item.stage))));
  return <section className="admin-owner-panel"><div className="admin-owner-panel-heading"><div><span className="eyebrow">ADMINISTRATION · CONTRACTS</span><h3>Contract workflow configuration</h3><h4>Contracts</h4><p className="admin-owner-copy">Owner-controlled Contract records derived from an exact accepted Proposal revision.</p></div><span className="admin-owner-status">{contracts.length} record(s)</span></div><div className="admin-owner-definition-list"><b>Contract reference</b><span>{data.contract_reference_rule || "C-DEMO-### · unique · Owner controlled"}</span><b>Proposal → Contract</b><span>{data.eligibility || "Accepted Proposal revision required; no automatic legal Contract."}</span><b>Contract → Project</b><span>Explicit human Project Activation only; Contract existence does not activate a Project.</span></div><div className="proposals-toolbar"><div className="filter-row">{[["ALL", "All Contracts"], ["NEEDS_ACTION", "Needs Action"], ["AUTHORITY_REVIEW", "Authority Review"], ["READY_CLOSE", "Ready / Close"]].map(([key, label]) => <button key={key} className={`filter ${filter === key ? "active" : ""}`} onClick={() => setFilter(key)}>{label}</button>)}</div><div className="admin-owner-edit"><select aria-label="Accepted Proposal for new Contract" value={proposalId} onChange={(event) => setProposalId(event.target.value)}><option value="">New Contract from accepted Proposal…</option>{proposals.map((item) => <option key={item.id} value={item.id}>{item.proposal} · {item.proposal_reference}</option>)}</select><button className="button-primary" onClick={create}>Create Contract</button></div></div><div className="admin-owner-table contract-owner-list"><div className="admin-permission-head"><b>Contract</b><b>Contract Ref</b><b>Stage</b><b>Amount</b><b>Close Date</b><b>Open</b></div>{visible.map((item) => <div className="admin-owner-row" key={item.id}><div><b>{item.contract || "Unnamed Contract"}</b><small>{item.client?.name || "Client pending"} · {item.project_opportunity_ref || "Project / Opportunity Ref pending"}</small></div><span>{item.contract_ref}</span><em>{item.stage}</em><span>{item.amount ? `${item.amount} ${item.currency || ""}` : "—"}</span><span>{item.close_date || "—"}</span><button className="text-button" onClick={() => onNavigate(`/admin/contracts/${item.id}`)}>Open →</button></div>)}{!visible.length && <div className="empty-state"><b>No Contracts match this view.</b><p>Create one from an accepted Proposal revision or adjust the filter.</p></div>}</div>{message && <div className="admin-owner-message" role="status">{message}</div>}<h4>Required Contract fields</h4><div className="admin-owner-chip-grid">{(data.required_fields || []).map((item: any) => <div key={item.label}><b>{item.label}</b><span>{item.status}</span></div>)}</div><button className="text-button" onClick={() => onNavigate("/admin/contracts/inputs/go-live")}>Open Contract Inputs &amp; Go-Live →</button><button className="text-button" onClick={() => onNavigate(data.template_route || "/admin/templates")}>View canonical templates →</button></section>;
}

function ContractSetup({ data, onNavigate }: { data: any; onNavigate: (route: string) => void }) {
  const [contracts, setContracts] = useState<any[]>([]);
  const [proposals, setProposals] = useState<any[]>([]);
  const [filter, setFilter] = useState("ALL");
  const [query, setQuery] = useState("");
  const [proposalId, setProposalId] = useState("");
  const [message, setMessage] = useState("");
  const load = async (search = query) => { try { const [contractData, proposalData] = await Promise.all([api<any>(`/api/admin/contracts?q=${encodeURIComponent(search)}`), api<any>("/api/bd/proposals")]); setContracts(contractData.items || []); setProposals((proposalData.items || []).filter((item: any) => item.contract_eligible)); } catch (cause) { setMessage(cause instanceof Error ? cause.message : "Contract list unavailable."); } };
  useEffect(() => { void load(""); }, []);
  const create = async () => { if (!proposalId) return setMessage("Select an accepted Proposal revision first."); try { const result = await api<any>("/api/admin/contracts", { method: "POST", body: JSON.stringify({ proposal_id: proposalId }) }); onNavigate(`/admin/contracts/${result.id}`); } catch (cause) { setMessage(cause instanceof Error ? cause.message : "Contract could not be created."); } };
  const visible = contracts.filter((item) => filter === "ALL" || (filter === "READY_CLOSE" ? ["READY", "ACTIVE", "CLOSED"].includes(item.stage) : filter === "NEEDS_ACTION" ? item.blockers_count > 0 : item.stage === filter));
  return <section className="admin-owner-panel"><div className="admin-owner-panel-heading"><div><span className="eyebrow">ADMINISTRATION · CONTRACTS</span><h3>Contract register</h3><p className="admin-owner-copy">One canonical Contract register: search by Contract, Client, or Project / Opportunity Reference. Close Date keeps its explicit expected/actual meaning.</p></div><span className="admin-owner-status">{contracts.length} record(s)</span></div><div className="admin-owner-definition-list"><b>Proposal → Contract</b><span>{data.eligibility || "Accepted Proposal revision required; no automatic legal Contract."}</span><b>Contract → Project</b><span>Explicit human Project Activation only; Contract existence does not activate a Project.</span></div><div className="proposals-toolbar"><div className="filter-row">{[["ALL", "All Contracts"], ["NEEDS_ACTION", "Needs Action"], ["AUTHORITY_REVIEW", "Authority Review"], ["READY_CLOSE", "Ready / Close"]].map(([key, label]) => <button key={key} className={`filter ${filter === key ? "active" : ""}`} onClick={() => setFilter(key)}>{label}</button>)}</div><div className="admin-owner-edit"><input aria-label="Search Contracts" placeholder="Search Contract, Client, or Project ref" value={query} onChange={(event) => setQuery(event.target.value)} onKeyDown={(event) => { if (event.key === "Enter") void load(); }} /><button className="button-secondary" onClick={() => void load()}>Search</button><select aria-label="Accepted Proposal for new Contract" value={proposalId} onChange={(event) => setProposalId(event.target.value)}><option value="">New Contract from accepted Proposal…</option>{proposals.map((item) => <option key={item.id} value={item.id}>{item.proposal} · {item.proposal_reference}</option>)}</select><button className="button-primary" onClick={create}>Create Contract</button></div></div><div className="admin-owner-table contract-owner-list"><div className="admin-permission-head"><b>Contract</b><b>Contract Ref</b><b>Stage</b><b>Amount</b><b>Close Date</b><b>Open</b></div>{visible.map((item) => <div className="admin-owner-row" key={item.id}><div><b>{item.contract_name || item.contract || "Unnamed Contract"}</b><small>{item.client?.name || "Client pending"} · {item.project_opportunity_ref || "Project / Opportunity Ref pending"} · {item.billing_readiness || "Billing setup pending"}</small></div><span>{item.contract_reference || item.contract_ref}</span><em>{item.stage}</em><span>{item.amount ? `${item.amount} ${item.currency || ""}` : "—"}</span><span>{item.close_date || "—"}<small>{item.close_date_meaning || "Explicit close-date meaning pending"}</small></span><button className="text-button" onClick={() => onNavigate(`/admin/contracts/${item.id}`)}>Open →</button></div>)}{!visible.length && <div className="empty-state"><b>No Contracts match this view.</b><p>Search again, adjust the lane, or create one from an accepted Proposal revision.</p></div>}</div>{message && <div className="admin-owner-message" role="status">{message}</div>}<h4>Required Contract fields</h4><div className="admin-owner-chip-grid">{(data.required_fields || []).map((item: any) => <div key={item.label}><b>{item.label}</b><span>{item.status}</span></div>)}</div><button className="text-button" onClick={() => onNavigate("/admin/contracts/inputs/go-live")}>Open Contract Inputs &amp; Go-Live →</button><button className="text-button" onClick={() => onNavigate(data.template_route || "/admin/templates")}>View canonical templates →</button></section>;
}

function ContractWorkbench({ data, onBack: _onBack, onRefresh, onNavigate }: { data: any; onBack: () => void; onRefresh: () => void; onNavigate: (route: string) => void }) {
  return <div className="contract-center">
    <ContractSectionNav />
    <ContractOverview data={data} />
    <ProposalOriginSection data={data} />
    <ClientEvidenceSection data={data} onRefresh={onRefresh} />
    <ClientContactsSection data={data} onRefresh={onRefresh} />
    <CommercialSection data={data} onRefresh={onRefresh} />
    <CommitmentSection data={data} kind="payment" onRefresh={onRefresh} />
    <CommitmentSection data={data} kind="input" onRefresh={onRefresh} />
    <CommitmentSection data={data} kind="deliverable" onRefresh={onRefresh} />
    <SourcesSection data={data} onNavigate={onNavigate} />
    <ReadinessSection data={data} onRefresh={onRefresh} />
    <ProjectActivationPanel data={data} onRefresh={onRefresh} />
    <BillingSummaryPanel data={data} onNavigate={onNavigate} />
    <ContractWorkspaceFooter data={data} />
  </div>;
}

const apiDocumentUrl = (path: string | null | undefined) => path ? (import.meta.env.VITE_API_URL || "").replace(/\/+$/, "") + path : "";

function ContractSectionNav() {
  const links = [
    ["overview", "Overview"], ["proposal-origin", "Proposal Origin"], ["client-evidence", "Client Document / LPO"],
    ["client-contacts", "Client & Contacts"], ["commercial", "Commercial Terms"], ["payment-terms", "Payment Terms"],
    ["documents-needed", "Client Inputs"], ["deliverables", "Deliverables"], ["sources", "Sources"],
    ["readiness", "Readiness & Review"], ["accept", "Accept Contract"], ["activation", "Project Activation"],
    ["billing", "Billing & Invoices"], ["work", "AMEC Work"], ["history", "History"],
  ];
  return <nav className="contract-section-nav" aria-label="Contract sections">{links.map(([id, label]) => <a key={id} href={"#" + id}>{label}</a>)}</nav>;
}

function ContractOverview({ data }: { data: any }) {
  const accepted = ["FINALIZED", "APPROVED", "EXECUTED_EVIDENCE_RECORDED"].includes(String(data.current_revision?.status || "").toUpperCase());
  const amount = data.contract?.amount ? String(data.contract.amount) + " " + (data.contract.currency || "") : "Amount not confirmed";
  return <section id="overview" className="admin-owner-panel contract-overview"><div className="admin-owner-panel-heading"><div><span className="eyebrow">CONTRACT WORKSPACE</span><h3>{data.contract?.reference || "Contract"}</h3><p className="admin-owner-copy">Contract Preparation · Revision {data.current_revision?.revision_number || "—"} · {accepted ? "Accepted internally" : "Draft"} · {accepted ? "Accepted internally" : "Not submitted for review"}</p></div><div className="contract-overview-context"><b>{data.client?.name || "Client pending"}</b><span>{amount}</span></div></div></section>;
}

function SourceBadge({ label }: { label?: string }) {
  const friendly: Record<string, string> = { CLIENT_MASTER: "Client Master", "Client master": "Client Master", "Client contact": "Client Contact", CONTRACT_REVISION: "Contract Revision", ContractRevision: "Contract Revision", ContractClientInputRequirement: "Contract Revision", ContractDeliverableCommitment: "Contract Revision", AcceptedProposalRevision: "Accepted Proposal", DocumentVersion: "Supporting document", Dashboard: "Dashboard", OWNER_DEFINITION_REQUIRED: "Needs confirmation" };
  return <span className="contract-source-badge">{friendly[label || ""] || label || "Needs confirmation"}</span>;
}

function ProposalOriginSection({ data }: { data: any }) {
  const origin = data.origin;
  return <section id="proposal-origin" className="admin-owner-panel contract-origin-panel"><div className="contract-card-heading"><div><span className="eyebrow">PROPOSAL ORIGIN</span><h3>{origin ? "Accepted Proposal" : "Legacy Contract"}</h3></div>{origin && <a className="text-button" href={"/opportunities/" + origin.proposal_id}>Open Proposal →</a>}</div>{origin ? <div className="admin-owner-definition-list"><b>Proposal</b><span>{origin.proposal_reference} · {origin.title}</span><b>Accepted Revision</b><span>Revision {origin.revision_number} · exact snapshot retained</span><b>Accepted Amount</b><span>{origin.snapshot?.fields?.price || data.contract?.amount || "Not recorded"}</span><b>Accepted By / At</b><span>{data.current_revision?.accepted_by || "Recorded in History"}{data.current_revision?.accepted_at ? " · " + new Date(data.current_revision.accepted_at).toLocaleString() : ""}</span></div> : <div className="contract-reconciliation-warning"><b>Proposal origin requires reconciliation</b><span>This legacy Contract has no accepted Proposal revision. Acceptance is blocked by the safe default policy.</span></div>}</section>;
}

function RequirednessLabel({ item }: { item: any }) {
  return <span className="contract-requiredness">{item?.requiredness?.label || "Requirement not configured"}</span>;
}

function ClientEvidenceSection({ data, onRefresh }: { data: any; onRefresh: () => void }) {
  const [message, setMessage] = useState("");
  const [form, setForm] = useState({ role: "CLIENT_DOCUMENT", filename: "", content: "" });
  const save = async () => {
    if (!form.filename || !form.content) { setMessage("Select a file before saving this version."); return; }
    try { await api("/api/admin/contracts/" + data.id + "/documents", { method: "POST", body: JSON.stringify({ source_role: form.role, source_filename: form.filename, content: form.content, reason: "Owner received " + (form.role === "LPO" ? "LPO" : "Client Document") }) }); setMessage((form.role === "LPO" ? "LPO" : "Client Document") + " version saved and linked to the Contract."); setForm({ ...form, filename: "" , content: "" }); onRefresh(); }
    catch (cause) { setMessage(cause instanceof Error ? cause.message : "Document version could not be saved."); }
  };
  const cards: any[] = [["Client Document", data.client_document, "CLIENT_DOCUMENT"], ["LPO", data.lpo, "LPO"]];
  return <section id="client-evidence" className="admin-owner-panel contract-evidence-section"><div className="admin-owner-panel-heading"><div><span className="eyebrow">CLIENT DOCUMENT / LPO</span><h3>Client Document / LPO</h3><p className="admin-owner-copy">Requiredness is shown only when it comes from a configured Contract policy.</p></div></div>{message && <div className="admin-owner-message" role="status">{message}</div>}<div className="contract-document-cards">{cards.map(([label, item, role]) => <article className="contract-document-card" key={String(role)}><div className="contract-card-heading"><div><span className="eyebrow">CONTRACT INPUT</span><h4>{label}</h4></div><RequirednessLabel item={item} /></div>{item?.document ? <><b>{item.document.filename}</b><small>Current version v{item.document.version_number} · {item.count || 1} version(s) · Supporting document</small>{item.document.download && <a className="text-button" href={apiDocumentUrl(item.document.download)} target="_blank" rel="noreferrer">Open current version →</a>}<span className="contract-document-status">Current version</span></> : <><b>Not received</b><small>No current version is linked to this Contract.</small><span className="contract-document-status">Not received</span></>}<button className="button-secondary" onClick={() => setForm({ ...form, role: String(role) })}>Add / Replace Version</button></article>)}</div><details className="contract-document-entry"><summary>Add or replace a supporting document</summary><div className="admin-owner-edit"><select aria-label="Contract document source role" value={form.role} onChange={(event) => setForm({ ...form, role: event.target.value })}><option value="CLIENT_DOCUMENT">Client Document</option><option value="LPO">LPO</option></select><label>Upload / Select file<input aria-label="Contract document file" type="file" accept=".pdf,.doc,.docx,.txt" onChange={(event) => { const file = event.target.files?.[0]; if (!file) return; const reader = new FileReader(); reader.onload = () => setForm({ ...form, filename: file.name, content: String(reader.result || "") }); reader.readAsText(file); }} /></label>{form.filename && <small>Selected: {form.filename}</small>}<button className="button-secondary" disabled={!form.filename || !form.content} onClick={save}>Save version</button></div></details></section>;
}

function ClientContactsSection({ data, onRefresh }: { data: any; onRefresh: () => void }) {
  const [editing, setEditing] = useState(false);
  const [fields, setFields] = useState<Record<string, string>>({});
  const [message, setMessage] = useState("");
  const labels: Record<string, string> = { client_name: "Client Name", client_company: "Client Company", cr_number: "CR No.", mobile: "Mobile No.", pin_number: "PIN No.", client_email: "Client Email" };
  const clientFields = data.client_fields || {};
  const beginEdit = () => { setFields(Object.fromEntries(Object.keys(labels).map((key) => [key, clientFields[key]?.value || ""]))); setEditing(true); };
  const save = async () => { try { await api("/api/admin/contracts/" + data.id + "/client-fields", { method: "PATCH", body: JSON.stringify({ ...fields, reason: "Owner confirmed Contract client fields" }) }); setMessage("Client fields saved as a new Contract revision."); setEditing(false); onRefresh(); } catch (cause) { setMessage(cause instanceof Error ? cause.message : "Client fields could not be saved."); } };
  return <section id="client-contacts" className="admin-owner-panel contract-client-panel"><div className="contract-card-heading"><div><span className="eyebrow">CLIENT &amp; CONTACTS</span><h3>Client &amp; Contacts</h3></div><button className="button-secondary" onClick={() => editing ? setEditing(false) : beginEdit()}>{editing ? "Cancel" : "Edit Client fields"}</button></div>{message && <div className="admin-owner-message" role="status">{message}</div>}<div className="contract-field-grid">{Object.entries(labels).map(([key, label]) => { const field: any = clientFields[key] || {}; const displayValue = field.display_value || (key === "pin_number" ? "Not configured" : "Needs confirmation"); return <div className="contract-field" key={key}><small>{label}</small>{editing ? <input aria-label={label} value={fields[key] || ""} placeholder={displayValue} onChange={(event) => setFields({ ...fields, [key]: event.target.value })} /> : <b>{displayValue}</b>}{field.diverged ? <SourceBadge label="CONTRACT_REVISION" /> : <SourceBadge label={field.source_label} />}</div>; })}</div><div className="admin-owner-safe"><b>{data.client_contacts?.length ? "Selected Contract contacts" : "No Contract contact selected"}</b><span>{data.client_contacts?.length ? data.client_contacts.map((contact: any) => contact.name + " · " + (contact.email || contact.phone || "contact details pending")).join(" · ") : "A general Client email or mobile is not silently used as a Contract contact."}</span></div>{editing && <div className="admin-owner-edit"><button className="button-primary" onClick={save}>Save Client fields</button></div>}</section>;
}

function CommercialSection({ data, onRefresh }: { data: any; onRefresh: () => void }) {
  const [editing, setEditing] = useState(false);
  const [message, setMessage] = useState("");
  const [terms, setTerms] = useState({ project_opportunity_ref: data.contract?.project_opportunity_ref || "", amount: data.contract?.amount || "", currency: data.contract?.currency || "", payment_condition_text: data.contract?.payment_condition_text || "", duration: data.contract?.duration || "", valuation_amount: data.contract?.valuation_amount || "", valuation_currency: data.contract?.valuation_currency || "", valuation_basis: data.contract?.valuation_basis || "", contracted_scope_text: data.contract?.contracted_scope_text || "", reason: "" });
  const save = async () => { if (!terms.reason.trim()) { setMessage("Add a change reason before saving this Contract revision."); return; } try { await api("/api/admin/contracts/" + data.id, { method: "PATCH", body: JSON.stringify(terms) }); setMessage("Contract revision saved. Earlier values remain in History."); setEditing(false); onRefresh(); } catch (cause) { setMessage(cause instanceof Error ? cause.message : "Contract terms could not be saved."); } };
  return <section id="commercial" className="admin-owner-panel contract-commercial-panels"><div className="admin-owner-panel-heading"><div><span className="eyebrow">PROJECT &amp; COMMERCIAL TERMS</span><h3>Project &amp; Commercial Terms</h3><p className="admin-owner-copy">Business fields come from the accepted Proposal snapshot or the current Contract revision. Reconciliation remains in Proposal Origin.</p></div><button className="button-secondary" onClick={() => setEditing(!editing)}>{editing ? "Cancel edit" : "Edit Contract Terms"}</button></div>{message && <div className="admin-owner-message" role="status">{message}</div>}<div className="contract-project-description"><b>Project Description</b><span>{data.contract?.project_description || "Not provided"}</span><SourceBadge label={data.origin ? "AcceptedProposalRevision" : "CONTRACT_REVISION"} /></div><div className="contract-field-grid contract-commercial-grid">{editing ? <><label>Project / Opportunity Ref<input aria-label="Project / Opportunity Ref" value={terms.project_opportunity_ref} onChange={(event) => setTerms({ ...terms, project_opportunity_ref: event.target.value })} /></label><label>Contract Amount<input aria-label="Contract Amount" value={terms.amount} onChange={(event) => setTerms({ ...terms, amount: event.target.value })} /></label><label>Currency<input aria-label="Currency" value={terms.currency} onChange={(event) => setTerms({ ...terms, currency: event.target.value })} /></label><label>Payment Condition<input aria-label="Payment Condition" value={terms.payment_condition_text} onChange={(event) => setTerms({ ...terms, payment_condition_text: event.target.value })} /></label><label>Project Duration<input aria-label="Project Duration" value={terms.duration} onChange={(event) => setTerms({ ...terms, duration: event.target.value })} /></label><label>Valuation Amount<input aria-label="Valuation Amount" value={terms.valuation_amount} onChange={(event) => setTerms({ ...terms, valuation_amount: event.target.value })} /></label><label>Valuation Currency<input aria-label="Valuation Currency" value={terms.valuation_currency} onChange={(event) => setTerms({ ...terms, valuation_currency: event.target.value })} /></label><label>Valuation Basis<input aria-label="Valuation Basis" value={terms.valuation_basis} onChange={(event) => setTerms({ ...terms, valuation_basis: event.target.value })} /></label><label className="contract-wide-field">Detailed Works / Contracted Scope<textarea aria-label="Detailed Works / Contracted Scope" value={terms.contracted_scope_text} onChange={(event) => setTerms({ ...terms, contracted_scope_text: event.target.value })} /></label><label className="contract-wide-field">Change Reason<input aria-label="Change Reason" placeholder="Why is this revision needed?" value={terms.reason} onChange={(event) => setTerms({ ...terms, reason: event.target.value })} /></label><div className="contract-wide-field"><button className="button-primary" onClick={save}>Save Contract Revision</button></div></> : <><ContractFact label="Project / Opportunity Ref" value={data.contract?.project_opportunity_ref || "Needs confirmation"} source={data.origin ? "AcceptedProposalRevision" : "CONTRACT_REVISION"} /><ContractFact label="Contract Amount" value={data.contract?.amount ? String(data.contract.amount) + " " + (data.contract.currency || "") : "Needs confirmation"} source="CONTRACT_REVISION" /><ContractFact label="Payment Condition" value={data.contract?.payment_condition_text || "Needs confirmation"} source="CONTRACT_REVISION" /><ContractFact label="Project Duration" value={data.contract?.duration || "Needs confirmation"} source={data.origin ? "AcceptedProposalRevision" : "CONTRACT_REVISION"} /><ContractFact label="Valuation Amount" value={data.contract?.valuation_amount ? String(data.contract.valuation_amount) + " " + (data.contract.valuation_currency || "") : "Not configured"} source="CONTRACT_REVISION" /><ContractFact label="Detailed Works / Contracted Scope" value={data.contract?.contracted_scope_text || "Needs confirmation"} source={data.origin ? "AcceptedProposalRevision" : "CONTRACT_REVISION"} /></>}</div><p className="admin-owner-note"><b>Payment Condition</b> is the agreed wording. <b>Payment Terms</b> below are the structured schedule used for billing setup.</p></section>;
}

function CommitmentSection({ data, kind, onRefresh }: { data: any; kind: "payment" | "input" | "deliverable"; onRefresh: () => void }) {
  const config: any = kind === "payment" ? { id: "payment-terms", title: "Payment Terms", label: "Payment Term", count: data.payment_terms?.length || 0, items: data.payment_terms || [], empty: "No payment terms have been added to this Contract revision.", endpoint: "commercial-terms" } : kind === "input" ? { id: "documents-needed", title: "Client Inputs & Documents Needed", label: "Client Input", count: data.documents_needed?.length || 0, items: data.documents_needed || [], empty: "No Client inputs or documents have been added to this Contract revision.", endpoint: "client-inputs" } : { id: "deliverables", title: "Deliverables / Contracted Works", label: "Deliverable", count: data.deliverable_commitments?.length || 0, items: data.deliverable_commitments || [], empty: "No deliverables have been added to this Contract revision.", endpoint: "deliverables" };
  const [open, setOpen] = useState(false);
  const [message, setMessage] = useState("");
  const [form, setForm] = useState({ first: "", second: "" });
  const add = async () => {
    if (!form.first.trim()) { setMessage("Enter a " + config.label.toLowerCase() + " name."); return; }
    if (kind === "payment" && !form.second.trim()) { setMessage("Enter the exact payment condition."); return; }
    try { const body = kind === "payment" ? { sequence: config.count + 1, label: form.first, term_text: form.second, reason: "Owner added a Contract payment term" } : kind === "input" ? { sequence: config.count + 1, title: form.first, description: form.second, reason: "Owner added a Client input requirement" } : { sequence: config.count + 1, name: form.first, description: form.second, reason: "Owner added a Contract deliverable" }; await api("/api/admin/contracts/" + data.id + "/" + config.endpoint, { method: "POST", body: JSON.stringify(body) }); setMessage(config.label + " added to this Contract revision."); setForm({ first: "", second: "" }); setOpen(false); onRefresh(); } catch (cause) { setMessage(cause instanceof Error ? cause.message : config.label + " could not be added."); }
  };
  return <section id={config.id} className="admin-owner-panel contract-structured-panel"><div className="contract-card-heading"><div><span className="eyebrow">CONTRACT COMMITMENT</span><h3>{config.title}</h3></div><span className="admin-owner-status">{config.count} recorded</span></div>{config.items.map((item: any) => <div className="admin-owner-row" key={item.id}><div><b>{item.label || item.title || item.name}</b><small>{item.term_text || item.description || "Description not recorded"} · {item.source_document ? "Supporting document" : "Contract revision"}</small></div><em>{item.required === false ? "Optional" : ownerStage(item.status)}</em></div>)}{!config.count && !open && <p className="admin-owner-note">{config.empty}</p>}{message && <div className="admin-owner-message" role="status">{message}</div>}<button className="button-secondary" aria-expanded={open} onClick={() => setOpen(!open)}>+ Add {config.label}</button>{open && <div className="admin-owner-edit"><input aria-label={config.label + " name"} placeholder={config.label} value={form.first} onChange={(event) => setForm({ ...form, first: event.target.value })} /><input aria-label={config.label + " description"} placeholder={kind === "payment" ? "Exact condition" : "Description / why needed"} value={form.second} onChange={(event) => setForm({ ...form, second: event.target.value })} /><button className="button-primary" onClick={add}>Save {config.label}</button><button className="text-button" onClick={() => setOpen(false)}>Cancel</button></div>}</section>;
}

function SourcesSection({ data, onNavigate }: { data: any; onNavigate: (route: string) => void }) {
  return <section id="sources" className="admin-owner-panel contract-source-panel"><div className="contract-card-heading"><div><span className="eyebrow">CONTRACT DOCUMENTS &amp; SOURCES</span><h3>Contract Documents &amp; Sources</h3></div><span className="admin-owner-status">Grouped source lineage</span></div>{(data.source_panel || []).filter((item: any) => item.key !== "contract_template").map((item: any) => <div className="contract-source-row" key={item.key}><div><b>{item.label}</b><small>{item.detail}</small></div><SourceBadge label={item.source} />{item.open ? <a className="text-button" href={String(item.open).startsWith("/api/") ? apiDocumentUrl(item.open) : item.open}>Open →</a> : <span className="admin-owner-note">Not available</span>}</div>)}<section id="template" className="contract-template-panel"><div><span className="eyebrow">CONTRACT TEMPLATE / CONFIGURATION</span><h4>Contract Template / Configuration</h4><p>{data.template ? "Dashboard template · Version " + data.template.version : "Not configured"}</p></div><button className="button-secondary" onClick={() => onNavigate("/admin/templates")}>Manage in Dashboard</button></section><p className="admin-owner-note">{data.template ? "The current Contract references the pinned Dashboard template version." : "Contract Artifact: Not available until Contract Template is configured."}</p></section>;
}

function ReadinessSection({ data, onRefresh }: { data: any; onRefresh: () => void }) {
  const [message, setMessage] = useState("");
  const accept = async () => { try { const result = await api<any>("/api/admin/contracts/" + data.id + "/accept", { method: "POST", body: JSON.stringify({ reason: "Owner accepted the exact current Contract revision", idempotency_key: "owner-accept:" + data.id + ":" + (data.current_revision?.id || "pending") }) }); setMessage(result.decision === "ALREADY_ACCEPTED" ? "Contract was already accepted; no duplicate action was created." : "Contract accepted. Project Activation and Billing remain separate."); onRefresh(); } catch (cause) { setMessage(cause instanceof Error ? cause.message : "Contract acceptance failed."); } };
  const blockers = data.readiness?.blockers || [];
  const accepted = ["FINALIZED", "APPROVED", "EXECUTED_EVIDENCE_RECORDED"].includes(String(data.current_revision?.status || "").toUpperCase());
  return <section id="readiness" className="admin-owner-panel contract-readiness-panel"><div className="admin-owner-panel-heading"><div><span className="eyebrow">READINESS &amp; REVIEW</span><h3>Readiness &amp; Review</h3><p className="admin-owner-copy">Acceptance is an internal AMEC control on the exact current Contract revision; it does not execute a legal agreement.</p></div><span className="admin-owner-status">{blockers.length ? "Needs review" : accepted ? "Accepted internally" : "Ready to accept"}</span></div>{blockers.length ? <div className="contract-blocker-list">{blockers.map((item: any) => <div className="contract-blocker" key={item.code}>⚠ {readinessLabel(item)}</div>)}</div> : <div className="admin-owner-safe">No configured blockers. Confirm the current revision and accepted source lineage before accepting.</div>}{message && <div className="admin-owner-message" role="status">{message}</div>}<div className="contract-accept-panel" id="accept"><div><span className="eyebrow">ACCEPT CONTRACT</span><h4>Accept Contract</h4><p className="admin-owner-copy">Internal AMEC acceptance only. Project Activation and Billing remain separate.</p></div><button className="button-primary" onClick={accept} disabled={blockers.length > 0 || accepted}>{accepted ? "Contract Accepted" : "Accept Contract"}</button></div></section>;
}

function ContractFact({ label, value, source }: { label: string; value: string; source: string }) { return <div className="contract-field"><small>{label}</small><b>{value}</b><SourceBadge label={source} /></div>; }

function billingLabel(value: unknown) {
  return ({ READY_FOR_BILLING_SETUP: "Ready to configure Billing", NEEDS_CONTRACT_AUTHORITY: "Not ready for billing", NEEDS_PAYMENT_TERM_REVIEW: "Payment terms need confirmation", NEEDS_PROJECT_ACTIVATION: "Project activation required by policy", NOT_READY: "Not ready for billing", READY: "Ready to configure Billing", ACTIVE: "Billing active" }[String(value || "").toUpperCase()] || human(value, "Not configured"));
}

function readinessLabel(item: any) {
  return ({ CONTRACT_ORIGIN_RECONCILIATION_REQUIRED: "Proposal origin needs reconciliation before this Contract can be accepted.", CONTRACT_AMOUNT_REQUIRED: "Contract Amount is required.", CONTRACT_CURRENCY_REQUIRED: "Contract Currency is required.", PROJECT_OPPORTUNITY_REFERENCE_REQUIRED: "Project / Opportunity Reference is required.", CONTRACT_TEMPLATE_REQUIRED: "A Contract Template must be configured in Dashboard.", CONTRACT_ACCEPTANCE_REQUIRED: "Accept Contract before Project Activation.", CONTRACT_LPO_REQUIRED: "LPO is required by the configured Contract policy.", LPO_REQUIRED: "LPO is required by the configured Contract policy." }[String(item?.code || "").toUpperCase()] || item?.label || "Owner review is required before continuing.");
}

function ProjectActivationPanel({ data, onRefresh }: { data: any; onRefresh: () => void }) {
  const [projectCode, setProjectCode] = useState("");
  const [startDate, setStartDate] = useState("");
  const [message, setMessage] = useState("");
  const accepted = ["FINALIZED", "APPROVED", "EXECUTED_EVIDENCE_RECORDED"].includes(String(data.current_revision?.status || "").toUpperCase()) || Boolean(data.activation);
  const activate = async () => { if (!projectCode || !startDate) { setMessage("Enter a Project Code and Project Start Date."); return; } try { const result = await api<any>("/api/admin/contracts/" + data.id + "/activate-project", { method: "POST", body: JSON.stringify({ project_code: projectCode, start_date: startDate, idempotency_key: "owner-activation:" + data.id + ":" + projectCode + ":" + startDate }) }); setMessage(result.created ? "Project activated and linked to this Contract." : "Project activation already exists; no duplicate was created."); onRefresh(); } catch (cause) { setMessage(cause instanceof Error ? cause.message : "Project activation could not be recorded."); } };
  return <section id="activation" className="admin-owner-panel contract-activation-panel"><div className="admin-owner-panel-heading"><div><span className="eyebrow">PROJECT ACTIVATION</span><h3>Project Activation</h3><p className="admin-owner-copy">{accepted ? "Enter the Project Code and Start Date to create the canonical Project link." : "Locked until Contract acceptance"}</p></div><span className="admin-owner-status">{data.activation ? "Activated" : accepted ? "Ready" : "Locked"}</span></div>{data.activation ? <div className="admin-owner-definition-list"><b>Project Code</b><span>{data.activation.project_code}</span><b>Project Start Date</b><span>{data.activation.start_date}</span><b>Activated by</b><span>{data.activation.activated_by}</span><b>Activated at</b><span>{new Date(data.activation.activated_at).toLocaleString()}</span></div> : <div className="admin-owner-edit"><label>Project Code<input aria-label="Project Code" placeholder="Enter Project Code" value={projectCode} disabled={!accepted} onChange={(event) => setProjectCode(event.target.value)} /></label><label>Project Start Date<input aria-label="Project Start Date" type="date" value={startDate} disabled={!accepted} onChange={(event) => setStartDate(event.target.value)} /></label><button className="button-primary" disabled={!accepted} onClick={activate}>Activate Project</button></div>}{message && <div className="admin-owner-message" role="status">{message}</div>}</section>;
}

function BillingSummaryPanel({ data, onNavigate }: { data: any; onNavigate: (route: string) => void }) {
  const billing = data.billing_readiness || {};
  const accepted = Boolean(data.readiness?.origin_resolved) && ["FINALIZED", "APPROVED", "EXECUTED_EVIDENCE_RECORDED"].includes(String(data.current_revision?.status || "").toUpperCase());
  const projectRequired = ["REQUIRED", "PROJECT_REQUIRED"].includes(String(billing.project_required_policy || "").toUpperCase());
  const checks = [["Contract exists", Boolean(data.id)], ["Contract accepted", accepted], ["Amount & currency confirmed", Boolean(data.contract?.amount && data.contract?.currency)], ["Payment terms confirmed", Boolean((data.payment_terms || []).length || data.contract?.payment_condition_text)], ...(projectRequired ? [["Project activated", Boolean(data.activation)]] : [])];
  return <section id="billing" className="admin-owner-panel contract-billing-summary"><div className="admin-owner-panel-heading"><div><span className="eyebrow">BILLING &amp; INVOICES</span><h3>Billing &amp; Invoices</h3><p className="admin-owner-copy">Billing uses this Contract’s approved commercial context. Project activation is shown only when the configured policy requires it.</p></div><button className="button-secondary" onClick={() => onNavigate("/admin/invoices")}>Open Billing &amp; Invoices</button></div><div className="contract-billing-checklist">{checks.map(([label, ok]) => <div key={String(label)}><span>{ok ? "✓" : "○"}</span><b>{label}</b></div>)}</div><div className="admin-owner-definition-list"><b>Status</b><span>{billingLabel(billing.status)}</span><b>Billing Plan</b><span>{billing.billing_plan_status ? billingLabel(billing.billing_plan_status) : "Not configured"}</span><b>Milestones / Invoices</b><span>{billing.billing_milestone_count ?? 0} / {billing.invoice_count ?? 0}</span></div></section>;
}

function ContractWorkspaceFooter({ data }: { data: any }) {
  return <div className="admin-owner-two-col contract-work-footer"><section id="work" className="admin-owner-panel"><h3>AMEC Work / Issues / Notifications</h3><div className="admin-owner-link-counts"><a href="/work"><b>{data.my_work?.length || 0}</b><span>View task(s)</span></a><a href="/issues"><b>{data.issues?.length || 0}</b><span>View issue(s)</span></a><a href="/notifications"><b>{data.notifications?.length || 0}</b><span>View notification(s)</span></a></div></section><section id="history" className="admin-owner-panel"><h3>History</h3><p>{data.history?.length || 0} event(s)</p><p className="admin-owner-note">Audit details retain the append-only record.</p><a className="text-button" href="#overview">Back to Overview ↑</a></section></div>;
}


function ContractInputs({ data }: { data: any }) { return <section className="admin-owner-panel"><span className="eyebrow">INPUTS &amp; GO-LIVE · ADMINISTRATION CONTRACTS</span><h3>Contract and Project setup inputs</h3><p className="admin-owner-copy">These are explicit Owner decisions. Safe defaults are visible, but production authority, numbering, evidence, and Synology details remain configurable.</p><div className="admin-owner-chip-grid">{(data.items || []).map((item: any) => <div key={item.key}><b>{item.title}</b><small>{item.requested_input}</small><span>{item.status}{item.safe_default !== undefined ? ` · default: ${String(item.safe_default)}` : ""}</span></div>)}</div><div className="admin-owner-safe"><b>{data.items?.length || 0} required Contract inputs are registered</b><span>Real Synology verification remains an external go-live dependency. Contract, Project, Client, Proposal, task, issue, and notification records remain canonical.</span></div></section>; }

function PermitSetup({ data }: { data: any }) { return <div className="admin-owner-two-col"><section className="admin-owner-panel"><span className="eyebrow">PERMIT WORKFLOW SETUP</span><h3>Requirements and attachments</h3><h4>Requirement applicability</h4>{(data.requirements || []).map((item: any) => <div className="admin-owner-row" key={item.name}><div><b>{item.name}</b><small>{item.description} · {item.applicability}</small></div><em>{item.status}</em></div>)}<h4>Attachment categories</h4>{(data.attachments || []).map((item: any) => <div className="admin-owner-row" key={item.label}><div><b>{item.label}</b><small>{item.formats?.join(", ") || "Configured formats"}</small></div><em>{item.required_state}</em></div>)}</section><section className="admin-owner-panel"><span className="eyebrow">MUNICIPALITY CONFIGURATION</span><h3>{data.municipality?.mode || "Needs AMEC Input"}</h3><div className="admin-owner-definition-list"><b>MFA</b><span>{data.municipality?.mfa}</span><b>Supported reads</b><span>{data.municipality?.supported_reads?.join(", ") || "Needs AMEC Input"}</span><b>Supported writes</b><span>{data.municipality?.supported_writes?.join(", ") || "Needs AMEC Input"}</span><b>Safety boundary</b><span>Reads and assisted preparation are simulated; final submission remains human-controlled.</span></div></section></div>; }

function Templates({ data }: { data: any }) { return <section className="admin-owner-panel"><span className="eyebrow">TEMPLATES &amp; DOCUMENTS</span><h3>Controlled template catalog</h3><div className="admin-owner-template-grid">{(data.templates || []).map((item: any) => <article key={item.id}><b>{item.name}</b><small>{item.purpose} · {item.owner_role}</small><span>{item.status}</span>{item.versions?.map((version: any) => <div key={version.version}>Version {version.version} · {version.status}</div>)}</article>)}</div><p className="admin-owner-note">Synthetic stand-ins are clearly marked. Production Proposal, Contract, Permit, and Municipality templates require AMEC confirmation.</p></section>; }

function Notifications({ data, onRefresh: _onRefresh }: { data: any; onRefresh: () => void }) { const [hours, setHours] = useState<number | "">(data.settings?.follow_up_hours ?? ""); const [message, setMessage] = useState(""); const save = async () => { setMessage(""); if (!hours || hours < 1 || hours > 720) { setMessage("Enter a follow-up time between 1 and 720 hours."); return; } try { await api("/api/admin/notifications/follow-up", { method: "PUT", body: JSON.stringify({ follow_up_hours: hours }) }); setMessage("Follow-up timing saved and audited."); } catch (cause) { setMessage(cause instanceof Error ? cause.message : "Configuration could not be saved."); } }; return <section className="admin-owner-panel"><span className="eyebrow">NOTIFICATIONS &amp; FOLLOW-UP</span><h3>Notification audiences and follow-up</h3><div className="admin-owner-chip-grid">{(data.audiences || []).map((item: any) => <div key={item.name}><b>{item.name}</b><small>{item.summary}</small><span>{item.status}</span></div>)}</div><div className="admin-owner-edit"><label>Follow-up reminder timing <input aria-label="Follow-up reminder timing" type="number" min="1" max="720" value={hours} onChange={(event) => setHours(event.target.value ? Number(event.target.value) : "")} /><small>Hours · synthetic test configuration until AMEC confirms policy.</small></label><button className="button-primary" onClick={save}>Save setting</button></div>{message && <div className="admin-owner-message" role="status">{message}</div>}<p className="admin-owner-note">Resulting notifications remain in the operational work surface; no external email is sent from this prototype.</p><div className="admin-owner-definition-list"><b>Delivery boundary</b><span>{data.delivery_boundary}</span><b>Recent events</b><span>{data.recent_event_count ?? 0} recorded operational events</span></div></section>; }

function Security({ data }: { data: any }) { const rows = [["Environment", data.environment?.label, data.environment?.status], ["Production data", data.data_classification?.label, data.data_classification?.status], ["MFA", data.mfa?.label, data.mfa?.status], ["Role-based access", data.role_based_access?.label, data.role_based_access?.status], ["Audit retention", data.audit_retention?.label, data.audit_retention?.status], ["Backup and recovery", data.backup_recovery?.label, data.backup_recovery?.status]]; return <section className="admin-owner-panel"><span className="eyebrow">DATA, SECURITY &amp; RETENTION</span><h3>Safe operating configuration</h3><div className="admin-owner-chip-grid">{rows.map(([label, detail, status]) => <div key={String(label)}><b>{label}</b><small>{detail}</small><span>{status}</span></div>)}</div><div className="admin-owner-safe"><b>Secrets exposed: No</b><span>Passwords, tokens, OTP values, database URLs, and authorization headers are not returned to this screen.</span></div></section>; }

function IntegrationHealth({ data, onNavigate }: { data: any; onNavigate: (route: string) => void }) { return <section className="admin-owner-panel"><div className="admin-owner-panel-heading"><div><span className="eyebrow">INTEGRATION HEALTH</span><h3>Cross-system health</h3></div><span className="admin-owner-status">Checked {data.checked_at ? new Date(data.checked_at).toLocaleString() : "—"}</span></div><p className="admin-owner-copy">{data.purpose}</p><div className="admin-owner-table">{(data.integrations || []).map((item: any) => <div className="admin-owner-row" key={item.name}><div><b>{item.name}</b><small>{item.affected_workflow}</small></div><span>{item.status}</span><em>{item.production_status}</em></div>)}</div><button className="text-button" onClick={() => onNavigate("/admin/data-connections")}>Manage source connections →</button></section>; }

function Audit({ data, onNavigate }: { data: any; onNavigate: (route: string) => void }) { return <section className="admin-owner-panel"><div className="admin-owner-panel-heading"><div><span className="eyebrow">AUDIT HISTORY</span><h3>Owner-readable operational history</h3></div><button className="button-secondary" onClick={() => onNavigate("/admin/advanced-diagnostics")}>Technical detail</button></div><div className="admin-owner-table">{(data.events || []).map((event: any) => <div className="admin-owner-row" key={event.id}><div><b>{event.action}</b><small>{event.record} · {event.when}</small></div><span>{event.actor}</span><em>{event.outcome}</em></div>)}</div></section>; }

function Advanced({ data, onNavigate }: { data: any; onNavigate: (route: string) => void }) { return <section className="admin-owner-panel admin-owner-advanced"><span className="eyebrow">ADVANCED DIAGNOSTICS · SECONDARY</span><h3>Technical evidence and diagnostics</h3><p>Technical IDs, hashes, adapter evidence, and synthetic fixture diagnostics stay separate from normal Owner configuration. No credentials or authorization material is shown.</p>{(data.diagnostics || []).map((item: any) => <button className="admin-owner-card" key={item.name} onClick={() => onNavigate(item.route)}><span><b>{item.name}</b><small>{item.purpose} · {item.status}</small></span><strong>→</strong></button>)}</section>; }
